import { test, expect } from '@playwright/test';

test.describe('Phone Number Field Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/contact-form');
  });

  test('should accept only numeric input in phone number field', async ({ page }) => {
    // Locate and interact with phone number input using getByLabel
    const phoneInput = page.getByLabel('Phone Number');
    await expect(phoneInput).toBeVisible();

    // Set up intercept to capture and verify API call
    await page.route('**/api/contact-form/validate-phone', (route) => {
      route.continue();
    });

    // Attempt to enter a valid numeric phone number
    await phoneInput.fill('1234567890');
    await expect(phoneInput).toHaveValue('1234567890');

    // Verify validation API is called
    await expect(page).toHaveReceivedCount(1, 'request', /contact-form\/validate-phone/);

    // Verify success message appears
    const successMessage = page.getByText('Phone number validated successfully');
    await expect(successMessage).toBeVisible();

    // Verify error message is not visible
    const errorMessage = page.getByText('Invalid phone number');
    await expect(errorMessage).not.toBeVisible();
  });

  test('should reject non-numeric input in phone number field', async ({ page }) => {
    // Locate and interact with phone number input using getByLabel
    const phoneInput = page.getByLabel('Phone Number');
    await expect(phoneInput).toBeVisible();

    // Set up intercept to capture and verify API call
    await page.route('**/api/contact-form/validate-phone', (route) => {
      route.continue();
    });

    // Attempt to enter a non-numeric value
    await phoneInput.fill('abc123');

    // Verify validation API is called
    await expect(page).toHaveReceivedCount(1, 'request', /contact-form\/validate-phone/);

    // Verify error message appears
    const errorMessage = page.getByText('Invalid phone number');
    await expect(errorMessage).toBeVisible();

    // Verify success message is not visible
    const successMessage = page.getByText('Phone number validated successfully');
    await expect(successMessage).not.toBeVisible();

    // Verify input is still present and retains non-numeric value
    await expect(phoneInput).toHaveValue('abc123');
  });
});
